"""Python half of the server parity test (go/internal/server/python_test.go).

  create VAULT_DIR MASTER_FILE TOKEN_FILE POLICY_FILE
      The REAL Python VaultManager creates a vault and writes secrets; the
      REAL Python FastAPI app (build_app, via TestClient) answers list, use,
      simulate and the capability listing. Prints the responses as JSON.

  verify VAULT_DIR MASTER_FILE POLICY_FILE
      After Go served writes on the same files: verify_audit_chain(), read
      back the Go-written secret and list the namespace. Prints JSON.

All key material is throwaway test data generated by the Go test.
"""

import hashlib
import json
import os
import sys

from rgt_vault.providers.base import MasterSecretProvider
from rgt_vault.vault import VaultManager


class FileMaster(MasterSecretProvider):
    def __init__(self, path):
        self.path = path

    def get_secret(self):
        with open(self.path, "rb") as f:
            return f.read()


def open_vault(vault_dir, master, policy_file):
    with open(policy_file) as f:
        policy = f.read()
    return VaultManager(
        db_path=os.path.join(vault_dir, "vault.db"),
        policy_yaml=policy,
        master_provider=FileMaster(master),
    )


def create(vault_dir, master, token_file, policy_file):
    from fastapi.testclient import TestClient

    from rgt_vault.server.app import build_app
    from rgt_vault.server.auth import TokenStore

    vm = open_vault(vault_dir, master, policy_file)
    vm.set_secret("alpha", "alpha-value", namespace="parity", agent="bot", purpose="ci")
    vm.set_secret("beta", "beta-v1", namespace="parity", agent="bot", purpose="ci", note="n1")
    vm.set_secret("beta", "beta-v2-ünï", namespace="parity", agent="bot", purpose="ci", note="n2")
    store = TokenStore(token_file)
    token = store.read()
    client = TestClient(build_app(vm, store))
    h = {"Authorization": "Bearer " + token}
    out = {
        "list": client.get("/v1/secrets", params={"namespace": "parity", "agent": "bot"}, headers=h).json(),
        "list_denied": client.get("/v1/secrets", params={"namespace": "parity", "agent": "intruder"}, headers=h).status_code,
        "use": client.post(
            "/v1/secrets/parity/alpha/use",
            json={"action": "echo", "agent": "bot", "purpose": "parity"},
            headers=h,
        ).json(),
        "use_missing": client.post(
            "/v1/secrets/parity/missing/use",
            json={"action": "echo", "agent": "bot", "purpose": "parity"},
            headers=h,
        ).status_code,
        "simulate": client.post(
            "/v1/policy/simulate", json={"agent": "intruder", "namespace": "parity"}, headers=h
        ).json(),
        "capabilities": client.get("/v1/capabilities", headers=h).json(),
        "fingerprint_beta": vm.get_fingerprint("beta", namespace="parity"),
        "chain": vm.verify_audit_chain(),
    }
    print(json.dumps(out))


def verify(vault_dir, master, policy_file):
    vm = open_vault(vault_dir, master, policy_file)
    out = {"chain": vm.verify_audit_chain()}
    with vm.lease_secret("go-written", "bot", "parity", "python-verify") as buf:
        out["go_written_sha256"] = hashlib.sha256(bytes(buf)).hexdigest()
    with vm.lease_secret("beta", "bot", "parity", "python-verify") as buf:
        out["beta"] = bytes(buf).decode("utf-8")
    out["names"] = sorted(s["name"] for s in vm.list_secrets("parity", agent="bot"))
    out["key_epoch"] = vm.key_epoch
    out["chain_after_reads"] = vm.verify_audit_chain()
    print(json.dumps(out))


if __name__ == "__main__":
    if sys.argv[1] == "create":
        create(*sys.argv[2:6])
    elif sys.argv[1] == "verify":
        verify(*sys.argv[2:5])
    else:
        raise SystemExit("usage: pyserver.py create|verify ...")
